import { createClient } from "npm:@supabase/supabase-js@2";
import {
  readExactCurrentSessionAuthority,
  readExactPlatformRole,
} from "./exact-subject-authority.ts";

export type AuthenticatedUser = {
  email: string | null;
  id: string;
  sessionGeneration?: string;
};

type AuthResult = { user: AuthenticatedUser } | { error: Response };
type JsonObject = Record<string, unknown>;
// The Stripe foundation functions write to additive finance tables that may not
// be present in generated Supabase types at Deno-check time.
export type SupabaseClientLike = ReturnType<typeof createClient<any>>;

export type StripeConnectAccountPayload = {
  live_setup_disclosure?: unknown;
  creator_user_id?: unknown;
  creatorUserId?: unknown;
  provider_account_id?: unknown;
  providerAccountId?: unknown;
  requested_account_type?: unknown;
  requestedAccountType?: unknown;
};

export type StripeConnectOnboardingPayload = StripeConnectAccountPayload & {
  refresh_url?: unknown;
  refreshUrl?: unknown;
  return_url?: unknown;
  returnUrl?: unknown;
};

export type StripeConnectSyncPayload = StripeConnectAccountPayload;

type StripeRequirements = {
  currently_due?: unknown;
  eventually_due?: unknown;
  past_due?: unknown;
  disabled_reason?: unknown;
};

export type StripeAccountObject = {
  capabilities?: Record<string, unknown>;
  charges_enabled?: boolean;
  country?: string;
  default_currency?: string;
  details_submitted?: boolean;
  id?: string;
  livemode?: boolean;
  payouts_enabled?: boolean;
  requirements?: StripeRequirements | null;
  type?: unknown;
  controller?: {
    type?: unknown;
    is_controller?: unknown;
    fees?: { payer?: unknown } | null;
    losses?: { payments?: unknown } | null;
    requirement_collection?: unknown;
    stripe_dashboard?: { type?: unknown } | null;
  } | null;
};

export type StripeObservedConfiguration = {
  accountType: string;
  controllerType: string;
  isController: boolean | null;
  dashboardType: string;
  feesPayer: string;
  feesPayerRaw: string;
  lossesCollector: string;
  requirementsCollection: string;
  configurationStatus: "match" | "mismatch" | "unknown";
};

export type NormalizedStripeAccount = StripeObservedConfiguration & {
  cardPaymentsCapabilityStatus: string;
  chargesEnabled: boolean;
  country: string | null;
  defaultCurrency: string;
  detailsSubmitted: boolean;
  disabledReason: string | null;
  id: string;
  kycReady: boolean;
  legacyStatus: string;
  onboardingStatus: string;
  payoutsEnabled: boolean;
  providerReady: boolean;
  providerReportedReady: boolean;
  requirementsCurrentlyDue: string[];
  requirementsEventuallyDue: string[];
  requirementsPastDue: string[];
  transfersCapabilityStatus: string;
};

export type CreatorPayoutAccountRow = {
  id: string;
  creator_user_id: string;
  metadata?: unknown;
  onboarding_completed_at?: string | null;
  onboarding_started_at?: string | null;
  provider_account_id?: string | null;
  status?: string;
  provider?: string;
  provider_environment?: string;
  provider_account_type?: string;
  provider_controller_type?: string;
  provider_is_controller?: boolean | null;
  provider_dashboard_type?: string;
  provider_fees_payer?: string;
  provider_fees_payer_raw?: string;
  provider_losses_collector?: string;
  provider_requirements_collection?: string;
  provider_configuration_observed_at?: string | null;
  provider_configuration_account_id?: string | null;
};

export type StripeProviderEvent = {
  account?: string | null;
  // Untrusted event time: consumers must validate before using it as evidence.
  created?: unknown;
  data?: {
    object?: unknown;
  };
  id?: string;
  livemode?: boolean;
  type?: string;
};

export type StripeConnectTransferSyncPayload = {
  provider_payout_id?: unknown;
  provider_transfer_id?: unknown;
  provider_transfer_record_id?: unknown;
  providerPayoutId?: unknown;
  providerTransferId?: unknown;
  providerTransferRecordId?: unknown;
};

export type CreatorPayoutProviderTransferRow = {
  amount_minor?: number | null;
  created_at?: string | null;
  creator_user_id?: string | null;
  currency?: string | null;
  failure_code?: string | null;
  failure_message?: string | null;
  id: string;
  last_provider_sync_at?: string | null;
  metadata?: unknown;
  payout_account_id?: string | null;
  payout_entry_id?: number | null;
  platform_admin_audit_log_id?: string | null;
  provider?: string | null;
  provider_environment?: string | null;
  provider_payout_id?: string | null;
  provider_status?: string | null;
  provider_transfer_id?: string | null;
  status?: string | null;
};

export type StripeTransferObject = {
  amount?: number;
  created?: number;
  currency?: string;
  destination?: string | null;
  id?: string;
  livemode?: boolean;
  metadata?: Record<string, unknown>;
  object?: string;
  reversed?: boolean;
};

export type StripePayoutObject = {
  amount?: number;
  arrival_date?: number;
  created?: number;
  currency?: string;
  failure_code?: string | null;
  failure_message?: string | null;
  id?: string;
  livemode?: boolean;
  metadata?: Record<string, unknown>;
  object?: string;
  status?: string;
};

export const DB_PROVIDER = "stripe_connect";
export const RESPONSE_PROVIDER = "stripe";
export const PROVIDER_ENVIRONMENT = "test";
export const STRIPE_API_VERSION = "2026-02-25.clover";
export const STRIPE_CONNECT_EXPECTED_CONFIGURATION = {
  key: "stripe_connect_test_express_controller_v1",
  accountTypes: ["express", "none"],
  controllerType: "application",
  isController: true,
  dashboardType: "express",
  feesPayer: "platform",
  feesPayerRaw: ["application", "application_express"],
  lossesCollector: "platform",
  requirementsCollection: "stripe",
} as const;
export const STRIPE_CONNECT_FOUNDATION_WEBHOOK_EVENT_TYPES = [
  "account.updated",
  "checkout.session.completed",
  "checkout.session.async_payment_succeeded",
  "checkout.session.async_payment_failed",
  "payment_intent.succeeded",
  "payment_intent.payment_failed",
  "charge.refunded",
  "charge.dispute.created",
  "payout.paid",
  "payout.failed",
  "transfer.created",
  "transfer.reversed",
  "transfer.canceled",
] as const;

const STRIPE_API_BASE_URL = "https://api.stripe.com/v1";
const JSON_HEADERS = {
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, stripe-signature",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Origin": "*",
  "Content-Type": "application/json",
} as const;

const DEFAULT_ALLOWED_REDIRECT_ORIGINS = new Set([
  "https://chillywoodstream.com",
  "https://www.chillywoodstream.com",
]);

const DEFAULT_ALLOWED_DEEP_LINK_SCHEMES = new Set([
  "chillywoodmobile",
  "com.chillywood.mobile",
]);

export const jsonResponse = (status: number, payload: JsonObject) =>
  new Response(JSON.stringify(payload), {
    headers: JSON_HEADERS,
    status,
  });

export const optionsResponse = () => new Response("ok", { headers: JSON_HEADERS, status: 200 });

export const toText = (value: unknown) => String(value ?? "").trim();

export const sanitizeErrorMessage = (error: unknown) => {
  const raw = error instanceof Error ? error.message : String(error ?? "Unknown Stripe Connect provider error.");

  return raw
    .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, "Bearer [redacted]")
    .replace(/sk_(test|live)_[A-Za-z0-9_]+/gi, "sk_[redacted]")
    .replace(/rk_(test|live)_[A-Za-z0-9_]+/gi, "rk_[redacted]")
    .replace(/whsec_[A-Za-z0-9_]+/gi, "whsec_[redacted]")
    .replace(/[A-Za-z0-9._~+/=-]{64,}/g, "[redacted]")
    .slice(0, 280);
};

export const parseJsonPayload = async <Payload extends object>(req: Request): Promise<{ value: Payload } | { error: Response }> => {
  const rawBody = await req.text();
  if (!rawBody.trim()) return { value: {} as Payload };

  try {
    const parsed = JSON.parse(rawBody) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return { error: jsonResponse(400, { error: "invalid_body", message: "Request body must be a JSON object." }) };
    }

    return { value: parsed as Payload };
  } catch {
    return { error: jsonResponse(400, { error: "invalid_json", message: "Request body must be valid JSON." }) };
  }
};

export const readRequiredEnv = (key: string) => {
  const value = toText(Deno.env.get(key));
  if (!value) throw new Error(`Missing required environment variable: ${key}`);
  return value;
};

export const readOptionalEnv = (key: string) => toText(Deno.env.get(key)) || null;

export const readStripeTestSecret = () => {
  const value = readOptionalEnv("STRIPE_SECRET_KEY");
  if (!value) {
    return {
      configured: false as const,
      message: "Stripe Connect test-mode secret is not configured for this Edge Function.",
      reason: "stripe_secret_missing",
    };
  }

  if (!value.startsWith("sk_test_")) {
    return {
      configured: false as const,
      message: "Stripe secret is not a test-mode secret. Refusing provider calls.",
      reason: "stripe_secret_not_test_mode",
    };
  }

  return { configured: true as const, secret: value };
};

export const readStripeWebhookSecret = () => {
  const value = readOptionalEnv("STRIPE_WEBHOOK_SECRET");
  if (!value) {
    return {
      configured: false as const,
      message: "Stripe Connect webhook secret is not configured for this Edge Function.",
      reason: "stripe_webhook_secret_missing",
    };
  }

  if (!value.startsWith("whsec_")) {
    return {
      configured: false as const,
      message: "Stripe webhook secret is not in the expected server-side format. Refusing webhook processing.",
      reason: "stripe_webhook_secret_invalid",
    };
  }

  return { configured: true as const, secret: value };
};

export const createAuthClient = () => {
  const supabaseUrl = readRequiredEnv("SUPABASE_URL");
  const supabaseAnonKey = readRequiredEnv("SUPABASE_ANON_KEY");

  return {
    supabaseAnonKey,
    supabaseUrl,
  };
};

export const createAdminClient = () => {
  const supabaseUrl = readRequiredEnv("SUPABASE_URL");
  const serviceRoleKey = readOptionalEnv("SUPABASE_SERVICE_ROLE_KEY");
  if (!serviceRoleKey) {
    return {
      configured: false as const,
      message: "Supabase service role secret is not configured for provider-owned Edge Function writes.",
      reason: "service_role_missing",
    };
  }

  return {
    client: createClient(supabaseUrl, serviceRoleKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }),
    configured: true as const,
  };
};

export const authenticateRequest = async (
  req: Request,
  supabaseUrl: string,
  supabaseAnonKey: string,
): Promise<AuthResult> => {
  const authorization = toText(req.headers.get("Authorization"));
  if (!authorization.toLowerCase().startsWith("bearer ")) {
    return { error: jsonResponse(401, { error: "missing_authorization", message: "Bearer authorization is required." }) };
  }

  const authClient = createClient(supabaseUrl, supabaseAnonKey, {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
    global: {
      headers: {
        Authorization: authorization,
      },
    },
  });

  const { data, error } = await authClient.auth.getUser();
  const userId = toText(data.user?.id);
  const authority = !error && userId ? await readExactCurrentSessionAuthority(authClient, userId) : null;
  if (
    error ||
    !userId ||
    !authority
  ) {
    return { error: jsonResponse(401, { error: "invalid_session", message: "Supabase could not verify the current user session." }) };
  }

  return {
    user: {
      email: data.user?.email ?? null,
      id: userId,
      sessionGeneration: authority.sessionGeneration,
    },
  };
};

export const userHasPlatformRole = async (
  adminClient: SupabaseClientLike,
  user: AuthenticatedUser,
  roles: string[],
) => !!(await readExactPlatformRole(adminClient, user.id, roles));

export const requestedCreatorUserId = (payload: StripeConnectAccountPayload) =>
  toText(payload.creator_user_id ?? payload.creatorUserId);

export const hasClientProviderAccountId = (payload: StripeConnectAccountPayload) =>
  !!toText(payload.provider_account_id ?? payload.providerAccountId);

export const requestedAccountType = (payload: StripeConnectAccountPayload) =>
  toText(payload.requested_account_type ?? payload.requestedAccountType) || null;

export const notConfiguredPayload = (reason: string, message: string, extra: JsonObject = {}) => ({
  status: "not_configured",
  provider: RESPONSE_PROVIDER,
  providerKey: DB_PROVIDER,
  mode: PROVIDER_ENVIRONMENT,
  liveMoneyAction: false,
  providerCall: false,
  providerWrite: false,
  reason,
  message,
  ...extra,
});

const metadataObject = (value: unknown): JsonObject => {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value as JsonObject;
};

const redactMetadata = (value: unknown): unknown => {
  if (Array.isArray(value)) return value.map(redactMetadata);
  if (!value || typeof value !== "object") return value;

  return Object.fromEntries(
    Object.entries(value as JsonObject).map(([key, item]) => {
      const lowerKey = key.toLowerCase();
      if (
        lowerKey.includes("secret") ||
        lowerKey.includes("token") ||
        lowerKey.includes("password") ||
        lowerKey.includes("card") ||
        lowerKey.includes("bank") ||
        lowerKey.includes("identity_document")
      ) {
        return [key, "[redacted]"];
      }

      if (typeof item === "string") return [key, sanitizeErrorMessage(item)];
      return [key, redactMetadata(item)];
    }),
  );
};

const safeMetadata = (metadata: JsonObject = {}) =>
  redactMetadata({
    ...metadata,
    foundation_only: false,
    live_money_action: false,
    payout_execution: false,
    provider: RESPONSE_PROVIDER,
    provider_key: DB_PROVIDER,
    provider_environment: PROVIDER_ENVIRONMENT,
    stripe_api_version: STRIPE_API_VERSION,
    stripe_connect_test_mode: true,
  }) as JsonObject;

export const writeAuditLog = async (
  adminClient: SupabaseClientLike,
  input: {
    action: string;
    actorEmail?: string | null;
    actorRole?: string | null;
    actorUserId?: string | null;
    afterState?: unknown;
    beforeState?: unknown;
    metadata?: JsonObject;
    reason?: string | null;
    requestId?: string | null;
    severity?: string;
    targetId?: string | null;
    targetType?: string | null;
    targetUserId?: string | null;
  },
) => {
  const { data, error } = await adminClient
    .from("platform_admin_audit_logs")
    .insert({
      action: input.action,
      action_category: "payout",
      actor_email: input.actorEmail ?? null,
      actor_role: input.actorRole ?? "creator_self_service",
      actor_user_id: input.actorUserId ?? null,
      after_state: input.afterState == null ? null : (redactMetadata(input.afterState) as JsonObject),
      before_state: input.beforeState == null ? null : (redactMetadata(input.beforeState) as JsonObject),
      metadata: safeMetadata(input.metadata),
      reason: input.reason ?? "Stripe Connect test-mode provider action.",
      request_id: input.requestId ?? null,
      severity: input.severity ?? "info",
      target_id: input.targetId ?? null,
      target_type: input.targetType ?? null,
      target_user_id: input.targetUserId ?? null,
    })
    .select("id")
    .single();

  if (error) throw new Error(`Audit log insert failed: ${error.message}`);
  return toText((data as { id?: unknown } | null)?.id) || null;
};

export const safeWriteAuditLog = async (
  adminClient: SupabaseClientLike | null,
  input: Parameters<typeof writeAuditLog>[1],
) => {
  if (!adminClient) return null;

  try {
    return await writeAuditLog(adminClient, input);
  } catch {
    return null;
  }
};

const arrayOfStrings = (value: unknown): string[] => {
  if (!Array.isArray(value)) return [];

  return value
    .map((item) => toText(item))
    .filter(Boolean)
    .slice(0, 100);
};

const capabilityStatus = (value: unknown) => {
  const status = toText(value);
  if (["requested", "pending", "active", "inactive", "rejected"].includes(status)) return status;
  return status ? "unknown" : "not_requested";
};

const observedEnum = (value: unknown, supported: readonly string[]) =>
  typeof value === "string" && supported.includes(value) ? value : "unknown";

const observedOwner = (value: unknown, feePayer = false) => {
  if (value === "application" || (feePayer && (value === "application_express" || value === "application_custom"))) return "platform";
  if (!feePayer && value === "stripe") return "stripe";
  if (feePayer && value === "account") return "account";
  return "unknown";
};

const configurationStatus = (observed: Omit<StripeObservedConfiguration, "configurationStatus">): StripeObservedConfiguration["configurationStatus"] => {
  const expected = STRIPE_CONNECT_EXPECTED_CONFIGURATION;
  const comparisons = [
    [observed.accountType, expected.accountTypes.includes(observed.accountType as "express" | "none")],
    [observed.controllerType, observed.controllerType === expected.controllerType],
    [observed.dashboardType, observed.dashboardType === expected.dashboardType],
    [observed.feesPayer, observed.feesPayer === expected.feesPayer],
    [observed.feesPayerRaw, expected.feesPayerRaw.includes(observed.feesPayerRaw as "application" | "application_express")],
    [observed.lossesCollector, observed.lossesCollector === expected.lossesCollector],
    [observed.requirementsCollection, observed.requirementsCollection === expected.requirementsCollection],
  ] as const;
  if (observed.isController === false || comparisons.some(([value, matches]) => value !== "unknown" && !matches)) return "mismatch";
  if (observed.isController === null || comparisons.some(([value]) => value === "unknown")) return "unknown";
  return "match";
};

export const normalizeStripeConfiguration = (account: StripeAccountObject): StripeObservedConfiguration => {
  const controller = account.controller;
  const observed = {
    accountType: observedEnum(account.type, ["express", "standard", "custom", "none"]),
    controllerType: observedEnum(controller?.type, ["application", "account"]),
    isController: typeof controller?.is_controller === "boolean" ? controller.is_controller : null,
    dashboardType: observedEnum(controller?.stripe_dashboard?.type, ["express", "full", "none"]),
    feesPayer: observedOwner(controller?.fees?.payer, true),
    feesPayerRaw: observedEnum(controller?.fees?.payer, ["application", "application_express", "application_custom", "account"]),
    lossesCollector: observedOwner(controller?.losses?.payments),
    requirementsCollection: observedOwner(controller?.requirement_collection),
  };
  return { ...observed, configurationStatus: configurationStatus(observed) };
};

export const storedStripeConfiguration = (account: CreatorPayoutAccountRow): StripeObservedConfiguration => {
  // Historical fixed values are not evidence of an observed provider response.
  if (!account.provider_configuration_observed_at || !account.provider_account_id
    || account.provider_configuration_account_id !== account.provider_account_id
    || account.provider !== DB_PROVIDER || account.provider_environment !== PROVIDER_ENVIRONMENT) return normalizeStripeConfiguration({});
  const observed = {
    accountType: observedEnum(account.provider_account_type, ["express", "standard", "custom", "none"]),
    controllerType: observedEnum(account.provider_controller_type, ["application", "account"]),
    isController: typeof account.provider_is_controller === "boolean" ? account.provider_is_controller : null,
    dashboardType: observedEnum(account.provider_dashboard_type, ["express", "full", "none"]),
    feesPayer: observedEnum(account.provider_fees_payer, ["platform", "account", "stripe"]),
    feesPayerRaw: observedEnum(account.provider_fees_payer_raw, ["application", "application_express", "application_custom", "account"]),
    lossesCollector: observedEnum(account.provider_losses_collector, ["platform", "stripe"]),
    requirementsCollection: observedEnum(account.provider_requirements_collection, ["platform", "stripe"]),
  };
  return { ...observed, configurationStatus: configurationStatus(observed) };
};

export const stripeConfigurationNotice = (status: StripeObservedConfiguration["configurationStatus"]) => status === "mismatch"
  ? "The provider account configuration differs from the expected setup and needs platform review. Payouts remain inactive."
  : "Provider account configuration is not fully verified. Refresh provider status before continuing setup. Payouts remain inactive.";

export const safeStripeConfigurationPayload = (observed: StripeObservedConfiguration) => ({
  status: observed.configurationStatus,
  expected: STRIPE_CONNECT_EXPECTED_CONFIGURATION,
  observed: {
    account_type: observed.accountType,
    controller_type: observed.controllerType,
    is_controller: observed.isController,
    dashboard_type: observed.dashboardType,
    fees_payer: observed.feesPayer,
    fees_payer_raw: observed.feesPayerRaw,
    losses_collector: observed.lossesCollector,
    requirements_collection: observed.requirementsCollection,
  },
});

export const normalizeStripeAccount = (account: StripeAccountObject): NormalizedStripeAccount => {
  const id = toText(account.id);
  if (!id) throw new Error("Stripe account response did not include an account id.");
  if (account.livemode === true) throw new Error("Live-mode Stripe account responses are not processed.");
  const configuration = normalizeStripeConfiguration(account);

  const requirements = account.requirements ?? {};
  const currentlyDue = arrayOfStrings(requirements.currently_due);
  const eventuallyDue = arrayOfStrings(requirements.eventually_due);
  const pastDue = arrayOfStrings(requirements.past_due);
  const disabledReason = toText(requirements.disabled_reason) || null;
  const chargesEnabled = account.charges_enabled === true;
  const payoutsEnabled = account.payouts_enabled === true;
  const detailsSubmitted = account.details_submitted === true;
  const transfersCapabilityStatus = capabilityStatus(account.capabilities?.transfers);
  const cardPaymentsCapabilityStatus = capabilityStatus(account.capabilities?.card_payments);
  const providerReportedReady = payoutsEnabled && detailsSubmitted && !disabledReason && currentlyDue.length === 0 && pastDue.length === 0;
  const providerReady = providerReportedReady && configuration.configurationStatus === "match";
  const kycReady = detailsSubmitted && !disabledReason && currentlyDue.length === 0 && pastDue.length === 0;
  const onboardingStatus = (() => {
    if (disabledReason) return "payouts_disabled";
    if (configuration.configurationStatus !== "match") return "under_review";
    if (currentlyDue.length > 0 || pastDue.length > 0) return "action_required";
    if (providerReady) return "ready_for_payouts";
    if (detailsSubmitted) return "under_review";
    return "setup_required";
  })();
  const legacyStatus = (() => {
    if (disabledReason) return "pending_review";
    if (configuration.configurationStatus !== "match") return "pending_review";
    if (providerReady) return "eligible";
    if (currentlyDue.length > 0 || pastDue.length > 0) return "pending_kyc";
    if (!detailsSubmitted) return "setup_required";
    return "pending_review";
  })();

  return {
    ...configuration,
    cardPaymentsCapabilityStatus,
    chargesEnabled,
    country: toText(account.country) || null,
    defaultCurrency: toText(account.default_currency).toLowerCase() || "usd",
    detailsSubmitted,
    disabledReason,
    id,
    kycReady,
    legacyStatus,
    onboardingStatus,
    payoutsEnabled,
    providerReady,
    providerReportedReady,
    requirementsCurrentlyDue: currentlyDue,
    requirementsEventuallyDue: eventuallyDue,
    requirementsPastDue: pastDue,
    transfersCapabilityStatus,
  };
};

const accountMetadata = (
  existing: CreatorPayoutAccountRow | null,
  normalized: NormalizedStripeAccount,
  source: string,
) =>
  safeMetadata({
    ...metadataObject(existing?.metadata),
    last_provider_sync_source: source,
    provider_account_status: normalized.legacyStatus,
    provider_ready: normalized.providerReady,
    provider_reported_ready: normalized.providerReportedReady,
    provider_configuration: safeStripeConfigurationPayload(normalized),
    requirements_summary: {
      currently_due_count: normalized.requirementsCurrentlyDue.length,
      eventually_due_count: normalized.requirementsEventuallyDue.length,
      past_due_count: normalized.requirementsPastDue.length,
      disabled_reason_present: !!normalized.disabledReason,
    },
  });

export const readCreatorPayoutAccount = async (
  adminClient: SupabaseClientLike,
  creatorUserId: string,
  providerEnvironment?: "test" | "live",
) => {
  const { data, error } = await adminClient
    .from("creator_payout_accounts")
    .select("*")
    .eq("creator_user_id", creatorUserId)
    .eq("provider", DB_PROVIDER)
    .in("provider_environment", providerEnvironment ? [providerEnvironment] : ["live", "test"])
    .order("provider_environment", { ascending: true })
    .limit(1)
    .maybeSingle();

  if (error) throw new Error(`Payout account read failed: ${error.message}`);
  return (data ?? null) as CreatorPayoutAccountRow | null;
};

