const stripeUnixSecondsToIso = (value: unknown) => {
  const seconds = typeof value === "number" && Number.isFinite(value) ? value : null;
  if (!seconds) return null;
  return new Date(seconds * 1000).toISOString();
};

export const safeTransferStatusPayload = (row: CreatorPayoutProviderTransferRow) => ({
  amount_is_payable: false,
  checkout_created: false,
  creator_user_id: row.creator_user_id ?? null,
  currency: row.currency ?? "usd",
  failure_code: row.failure_code ?? null,
  failure_message_present: !!row.failure_message,
  local_transfer_record_id: row.id,
  live_money_action: false,
  payout_created: false,
  provider: row.provider ?? DB_PROVIDER,
  provider_environment: row.provider_environment ?? PROVIDER_ENVIRONMENT,
  provider_payout_id_present: !!row.provider_payout_id,
  provider_status: row.provider_status ?? null,
  provider_transfer_id_present: !!row.provider_transfer_id,
  status: row.status ?? "not_active",
  transfer_created: false,
});

export const normalizeStripeTransferStatus = (transfer: StripeTransferObject) => {
  if (transfer.livemode === true) {
    throw new Error("Live-mode Stripe transfer object was rejected by the test-mode sync foundation.");
  }

  const reversed = transfer.reversed === true;
  return {
    failureCode: null as string | null,
    failureMessage: null as string | null,
    localStatus: reversed ? "reversed_later" : "synced_test",
    providerCreatedAt: stripeUnixSecondsToIso(transfer.created),
    providerStatus: reversed ? "reversed" : "created",
  };
};

export const normalizeStripePayoutStatus = (payout: StripePayoutObject) => {
  if (payout.livemode === true) {
    throw new Error("Live-mode Stripe payout object was rejected by the test-mode sync foundation.");
  }

  const providerStatus = toText(payout.status).toLowerCase() || "unknown";
  const localStatus = (() => {
    if (providerStatus === "pending") return "pending_later";
    if (providerStatus === "in_transit") return "in_transit_later";
    if (providerStatus === "paid") return "paid_later";
    if (providerStatus === "failed") return "failed_later";
    if (providerStatus === "canceled" || providerStatus === "cancelled") return "cancelled_later";
    return "synced_test";
  })();

  return {
    estimatedArrivalAt: stripeUnixSecondsToIso(payout.arrival_date),
    failureCode: toText(payout.failure_code) || null,
    failureMessage: toText(payout.failure_message) || null,
    localStatus,
    providerCreatedAt: stripeUnixSecondsToIso(payout.created),
    providerStatus,
  };
};

export const updateProviderTransferSyncResult = async (
  adminClient: SupabaseClientLike,
  row: CreatorPayoutProviderTransferRow,
  input: {
    auditLogId?: string | null;
    estimatedArrivalAt?: string | null;
    failureCode?: string | null;
    failureMessage?: string | null;
    providerCreatedAt?: string | null;
    providerStatus: string;
    source: string;
    status: string;
  },
) => {
  const now = new Date().toISOString();
  const metadata = safeMetadata({
    ...metadataObject(row.metadata),
    last_provider_sync_source: input.source,
    provider_status_imported: true,
    status_import_only: true,
    transfer_creation: false,
    payout_creation: false,
  });

  const { data, error } = await adminClient
    .from("creator_payout_provider_transfers")
    .update({
      estimated_arrival_at: input.estimatedArrivalAt ?? null,
      failure_code: input.failureCode ?? null,
      failure_message: input.failureMessage ?? null,
      last_provider_sync_at: now,
      metadata,
      platform_admin_audit_log_id: input.auditLogId ?? row.platform_admin_audit_log_id ?? null,
      provider_created_at: input.providerCreatedAt ?? null,
      provider_status: input.providerStatus,
      status: input.status,
      updated_at: now,
    })
    .eq("id", row.id)
    .select("*")
    .single();

  if (error) throw new Error(`Provider transfer sync update failed: ${error.message}`);
  return data as CreatorPayoutProviderTransferRow;
};

export const createStripeConnectOnboardingLink = async (
  secret: string,
  providerAccountId: string,
  returnUrl: string,
  refreshUrl: string,
) =>
  stripeRequest<{ created?: number; expires_at?: number; object?: string; url?: string }>(secret, "/account_links", {
    body: {
      account: providerAccountId,
      refresh_url: refreshUrl,
      return_url: returnUrl,
      type: "account_onboarding",
    },
    idempotencyKey: `chillywood-stripe-connect-link-${providerAccountId}-${crypto.randomUUID()}`,
    method: "POST",
  });

export const insertOnboardingSession = async (
  adminClient: SupabaseClientLike,
  input: {
    account: CreatorPayoutAccountRow;
    auditLogId: string | null;
    createdByUserId: string;
    expiresAt: string | null;
    refreshUrl: string;
    returnUrl: string;
  },
) => {
  const now = new Date().toISOString();
  const { error } = await adminClient.from("creator_payout_onboarding_sessions").insert({
    created_by_user_id: input.createdByUserId,
    creator_user_id: input.account.creator_user_id,
    expires_at: input.expiresAt,
    metadata: safeMetadata({
      onboarding_url_stored: false,
      return_url_origin: safeUrlOrigin(input.returnUrl),
      refresh_url_origin: safeUrlOrigin(input.refreshUrl),
    }),
    onboarding_url_created_at: now,
    payout_account_id: input.account.id,
    platform_admin_audit_log_id: input.auditLogId,
    provider: DB_PROVIDER,
    provider_account_id: input.account.provider_account_id ?? null,
    provider_environment: PROVIDER_ENVIRONMENT,
    refresh_url: input.refreshUrl,
    return_url: input.returnUrl,
    status: "link_created",
    updated_at: now,
  });

  if (error) throw new Error(`Onboarding session insert failed: ${error.message}`);
};

const allowedRedirectOrigins = () => {
  const configured = readOptionalEnv("STRIPE_CONNECT_ALLOWED_REDIRECT_ORIGINS");
  const values = new Set(DEFAULT_ALLOWED_REDIRECT_ORIGINS);
  if (!configured) return values;

  configured
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean)
    .forEach((item) => {
      try {
        const parsed = new URL(item);
        values.add(parsed.origin.toLowerCase());
      } catch {
        const scheme = item.replace(/:$/, "").toLowerCase();
        if (scheme) values.add(`${scheme}:`);
      }
    });

  return values;
};

export const safeUrlOrigin = (rawUrl: string) => {
  try {
    const parsed = new URL(rawUrl);
    if (parsed.protocol === "http:" || parsed.protocol === "https:") return parsed.origin.toLowerCase();
    return parsed.protocol.toLowerCase();
  } catch {
    return "invalid";
  }
};

export const resolveRedirectUrls = (payload: StripeConnectOnboardingPayload): { value: { refreshUrl: string; returnUrl: string } } | { error: Response } => {
  const returnUrl = toText(payload.return_url ?? payload.returnUrl) || readOptionalEnv("STRIPE_CONNECT_RETURN_URL");
  const refreshUrl = toText(payload.refresh_url ?? payload.refreshUrl) || readOptionalEnv("STRIPE_CONNECT_REFRESH_URL");

  if (!returnUrl || !refreshUrl) {
    return {
      error: jsonResponse(400, {
        error: "redirect_url_required",
        message: "return_url and refresh_url are required before an onboarding link can be created.",
      }),
    };
  }

  const returnUrlError = validateAllowedRedirectUrl(returnUrl, "return_url");
  const refreshUrlError = validateAllowedRedirectUrl(refreshUrl, "refresh_url");
  if (returnUrlError || refreshUrlError) {
    return {
      error: jsonResponse(400, {
        error: "invalid_redirect_url",
        message: returnUrlError ?? refreshUrlError,
      }),
    };
  }

  return { value: { refreshUrl, returnUrl } };
};

const validateAllowedRedirectUrl = (rawUrl: string, fieldName: string) => {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    return `${fieldName} must be a valid URL.`;
  }

  if (parsed.username || parsed.password) return `${fieldName} must not include credentials.`;
  if (rawUrl.length > 2048) return `${fieldName} is too long.`;

  const protocol = parsed.protocol.toLowerCase();
  if (protocol === "https:") {
    const allowedOrigins = allowedRedirectOrigins();
    if (!allowedOrigins.has(parsed.origin.toLowerCase())) {
      return `${fieldName} origin is not allowed for Stripe Connect onboarding.`;
    }
    return null;
  }

  if (protocol === "http:") {
    return `${fieldName} must use https or the Chi'llywood app deep-link scheme.`;
  }

  const scheme = protocol.replace(/:$/, "");
  const envAllowsScheme = allowedRedirectOrigins().has(protocol);
  if (!DEFAULT_ALLOWED_DEEP_LINK_SCHEMES.has(scheme) && !envAllowsScheme) {
    return `${fieldName} scheme is not allowed for Stripe Connect onboarding.`;
  }

  return null;
};

const unixSecondsToIso = (value: unknown) => {
  const seconds = typeof value === "number" && Number.isFinite(value) ? value : null;
  if (!seconds) return null;
  return new Date(seconds * 1000).toISOString();
};

export const onboardingLinkExpiresAt = (value: unknown) => unixSecondsToIso(value);

export const verifyStripeWebhookSignature = async (rawBody: string, signatureHeader: string | null, webhookSecret: string) => {
  const header = toText(signatureHeader);
  if (!header) return false;

  const parts = header.split(",").map((item) => item.trim());
  const timestamp = toText(parts.find((part) => part.startsWith("t="))?.slice(2));
  const signatures = parts
    .filter((part) => part.startsWith("v1="))
    .map((part) => part.slice(3))
    .filter(Boolean);

  if (!timestamp || signatures.length === 0) return false;

  const timestampSeconds = Number(timestamp);
  if (!Number.isFinite(timestampSeconds)) return false;
  const ageSeconds = Math.abs(Date.now() / 1000 - timestampSeconds);
  if (ageSeconds > 300) return false;

  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey("raw", encoder.encode(webhookSecret), { hash: "SHA-256", name: "HMAC" }, false, [
    "sign",
  ]);
  const signedPayload = `${timestamp}.${rawBody}`;
  const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(signedPayload));
  const expectedHex = Array.from(new Uint8Array(signature))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");

  return signatures.some((provided) => timingSafeEqualHex(expectedHex, provided));
};

const timingSafeEqualHex = (expected: string, provided: string) => {
  if (!/^[a-f0-9]+$/i.test(provided)) return false;

  const expectedBytes = hexToBytes(expected);
  const providedBytes = hexToBytes(provided);
  if (expectedBytes.length !== providedBytes.length) return false;

  let result = 0;
  for (let index = 0; index < expectedBytes.length; index += 1) {
    result |= expectedBytes[index] ^ providedBytes[index];
  }

  return result === 0;
};

const hexToBytes = (value: string) => {
  const bytes = new Uint8Array(value.length / 2);
  for (let index = 0; index < bytes.length; index += 1) {
    bytes[index] = Number.parseInt(value.slice(index * 2, index * 2 + 2), 16);
  }
  return bytes;
};

export const parseStripeEvent = (rawBody: string) => {
  const parsed = JSON.parse(rawBody) as unknown;
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("Stripe webhook body was not an event object.");
  const event = parsed as StripeProviderEvent;
  if (!toText(event.id) || !toText(event.type)) throw new Error("Stripe webhook event is missing id or type.");
  return event;
};

export const stripeAccountFromEvent = (event: StripeProviderEvent) => {
  const object = event.data?.object;
  if (!object || typeof object !== "object" || Array.isArray(object)) return null;
  return object as StripeAccountObject;
};

export const isStripeConnectFoundationWebhookEventType = (eventType: string) =>
  STRIPE_CONNECT_FOUNDATION_WEBHOOK_EVENT_TYPES.includes(
    eventType as (typeof STRIPE_CONNECT_FOUNDATION_WEBHOOK_EVENT_TYPES)[number],
  );

export const insertProviderWebhookEvent = async (
  adminClient: SupabaseClientLike,
  event: StripeProviderEvent,
  providerAccountId: string | null,
) => {
  const eventId = toText(event.id);
  const eventType = toText(event.type);
  const { data, error } = await adminClient
    .from("creator_payout_provider_webhook_events")
    .insert({
      connected_account_id: toText(event.account) || null,
      event_id: eventId,
      event_type: eventType,
      idempotency_key: `stripe-connect-webhook-${eventId}`,
      livemode: event.livemode === true,
      metadata: safeMetadata({
        event_type: eventType,
        raw_event_stored: false,
      }),
      provider: DB_PROVIDER,
      provider_account_id: providerAccountId,
      provider_environment: PROVIDER_ENVIRONMENT,
      status: "received",
    })
    .select("*")
    .single();

  if (error && error.code === "23505") {
    const { data: existing, error: readError } = await adminClient
      .from("creator_payout_provider_webhook_events")
      .select("*")
      .eq("provider", DB_PROVIDER)
      .eq("provider_environment", PROVIDER_ENVIRONMENT)
      .eq("event_id", eventId)
      .maybeSingle();

    if (readError) throw new Error(`Webhook event duplicate lookup failed: ${readError.message}`);
    if (!existing || existing.event_id !== eventId || existing.event_type !== eventType
      || existing.provider !== DB_PROVIDER || existing.provider_environment !== PROVIDER_ENVIRONMENT
      || existing.provider_account_id !== providerAccountId
      || existing.connected_account_id !== (toText(event.account) || null)
      || existing.livemode !== false || event.livemode !== false) {
      throw new Error("Stripe Connect webhook retry does not match the stored event binding.");
    }
    return { duplicate: true as const, row: existing as { id?: string; status?: string } | null };
  }

  if (error) throw new Error(`Webhook event insert failed: ${error.message}`);
  return { duplicate: false as const, row: data as { id?: string; status?: string } | null };
};

export const updateProviderWebhookEvent = async (
  adminClient: SupabaseClientLike,
  rowId: string,
  input: {
    auditLogId?: string | null;
    failureReason?: string | null;
    metadata?: JsonObject;
    status: "processed" | "ignored" | "failed" | "retry_required";
  },
) => {
  const { error } = await adminClient
    .from("creator_payout_provider_webhook_events")
    .update({
      failure_reason: input.failureReason ?? null,
      metadata: safeMetadata(input.metadata ?? {}),
      platform_admin_audit_log_id: input.auditLogId ?? null,
      processed_at: new Date().toISOString(),
      status: input.status,
      updated_at: new Date().toISOString(),
    })
    .eq("id", rowId)
    .in("status", ["received", "failed", "retry_required"]);

  if (error) throw new Error(`Webhook event update failed: ${error.message}`);
};

export const safeRequirementsSummary = (normalized: NormalizedStripeAccount) => ({
  currentlyDueCount: normalized.requirementsCurrentlyDue.length,
  eventuallyDueCount: normalized.requirementsEventuallyDue.length,
  pastDueCount: normalized.requirementsPastDue.length,
  disabledReasonPresent: !!normalized.disabledReason,
});

export const safeAccountStatusPayload = (normalized: NormalizedStripeAccount) => ({
  charges_enabled: normalized.chargesEnabled,
  details_submitted: normalized.detailsSubmitted,
  onboarding_status: normalized.onboardingStatus,
  payout_execution_active: false,
  payouts_enabled: normalized.payoutsEnabled,
  provider_account_status: normalized.legacyStatus,
  provider_account_type: normalized.accountType,
  provider_configuration: safeStripeConfigurationPayload(normalized),
  provider_reported_ready: normalized.providerReportedReady,
  provider_ready: normalized.providerReady,
  requirements: safeRequirementsSummary(normalized),
});

files.supabase/functions/create-creator-tip-ch:
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

import {
  authenticateRequest,
  createAdminClient,
  createAuthClient,
  jsonResponse,
  notConfiguredPayload,
  optionsResponse,
  parseJsonPayload,
  readCreatorPayoutAccount,
  readStripeTestSecret,
  safeWriteAuditLog,
  sanitizeErrorMessage,
  storedStripeConfiguration,
  toText,
  type AuthenticatedUser,
  type CreatorPayoutAccountRow,
  type SupabaseClientLike,
} from "../_shared/stripe-connect.ts";

const FUNCTION_NAME = "create-creator-tip-checkout";
const STRIPE_API_BASE_URL = "https://api.stripe.com/v1";
const STRIPE_API_VERSION = "2026-02-25.clover";
const DEFAULT_SUCCESS_URL = "chillywoodmobile://tip-status";
const DEFAULT_CANCEL_URL = "chillywoodmobile://tip-status";

type TipCheckoutPayload = {
  amount_cents?: unknown;
  amountCents?: unknown;
  cancel_url?: unknown;
  cancelUrl?: unknown;
  creator_id?: unknown;
  creatorId?: unknown;
  currency?: unknown;
  private_note?: unknown;
  privateNote?: unknown;
  return_url?: unknown;
  returnUrl?: unknown;
  request_id?: unknown;
  requestId?: unknown;
  capability_id?: unknown;
  google_play_external_transaction_token?: unknown;
  google_play_external_link_api_version?: unknown;
};

type StripeCheckoutSession = {
  id?: string;
  livemode?: boolean;
  payment_intent?: string | null;
  url?: string | null;
  client_reference_id?: string;
  amount_total?: number;
  currency?: string;
  status?: string;
  expires_at?: number;
  metadata?: Record<string,string>;
};

type TipSettingsRow = {
  creator_id: string;
  currency?: string | null;
  max_amount_cents?: number | null;
  min_amount_cents?: number | null;
  provider_charges_enabled?: boolean | null;
  provider_payouts_enabled?: boolean | null;
  status?: string | null;
  tips_enabled?: boolean | null;
};

type PayoutAccountRow = CreatorPayoutAccountRow & {
  charges_enabled?: boolean | null;
  onboarding_status?: string | null;
  payouts_enabled?: boolean | null;
  provider_account_id?: string | null;
  status?: string | null;
};

type BuyerSessionAuthority = {
  userId: string;
  accountId: string;
  sessionGeneration: string;
};

const allowedWebOrigins = new Set([
  "https://chillywoodstream.com",
  "https://www.chillywoodstream.com",
]);

const allowedDeepLinkProtocols = new Set([
  "chillywoodmobile:",
  "com.chillywood.mobile:",
]);

const toAmountCents = (value: unknown) => {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : null;
};

const normalizeUuid = (value: unknown) => {
  const text = toText(value);
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text)
    ? text
    : null;
};

const normalizeBuyerSessionAuthority = (
  value: unknown,
  expectedUserId: string,
): BuyerSessionAuthority | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const row = value as Record<string, unknown>;
  const userId = normalizeUuid(row.userId);
  const accountId = normalizeUuid(row.accountId);
  const sessionGeneration = normalizeUuid(row.sessionGeneration);
  if (
    row.authoritative !== true
    || row.state !== "ACTIVE"
    || row.restoreOnly !== false
    || !userId
    || userId !== expectedUserId
    || accountId !== userId
    || !sessionGeneration
  ) return null;
  return { userId, accountId, sessionGeneration };
};

const readBuyerSessionAuthority = async (
  client: SupabaseClientLike,
  expectedUserId: string,
) => {
  try {
    const { data, error } = await client.rpc("wave1_session_authority_readback");
    return error ? null : normalizeBuyerSessionAuthority(data, expectedUserId);
  } catch {
    return null;
  }
};

const sameBuyerSessionAuthority = (
  left: BuyerSessionAuthority,
  right: BuyerSessionAuthority | null,
) => !!right
  && left.userId === right.userId
  && left.accountId === right.accountId
  && left.sessionGeneration === right.sessionGeneration;

const sanitizePrivateNote = (value: unknown) => {
  const note = toText(value)
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return note ? note.slice(0, 280) : null;
};

const safeRedirectUrl = (value: unknown, fallback: string, tipId: string) => {
  const raw = toText(value) || fallback;
  try {
    const parsed = new URL(raw);
    if (!allowedWebOrigins.has(parsed.origin) && !allowedDeepLinkProtocols.has(parsed.protocol)) {
      const safe = new URL(fallback); safe.searchParams.set("tip_id", tipId); return safe.toString();
    }
    parsed.searchParams.set("tip_id", tipId);
    return parsed.toString();
  } catch {
    const parsed = new URL(fallback);
    parsed.searchParams.set("tip_id", tipId);
    return parsed.toString();
  }
};

const encodeStripeForm = (params: Record<string, unknown>) => {
  const form = new URLSearchParams();
  Object.entries(params).forEach(([key, value]) => {
    if (value === undefined || value === null || value === "") return;
    form.append(key, String(value));
  });
  return form;
};

const stripeRequest = async <T extends object>(
  secret: string,
  path: string,
  input?: { body: Record<string, unknown>; idempotencyKey: string },
) => {
  const response = await fetch(`${STRIPE_API_BASE_URL}${path}`, {
    body: input ? encodeStripeForm(input.body) : undefined,
    headers: {
      Authorization: `Bearer ${secret}`,
      "Content-Type": "application/x-www-form-urlencoded",
      ...(input ? { "Idempotency-Key": input.idempotencyKey } : {}),
      "Stripe-Version": STRIPE_API_VERSION,
    },
    method: input ? "POST" : "GET",
    signal: AbortSignal.timeout(15_000), redirect: "error",
  });
  const payload = (await response.json().catch(() => null)) as (T & { error?: { message?: string; type?: string } }) | null;
  if (!response.ok) {
    const message = payload?.error?.message
      ? `${payload.error.type ?? "stripe_error"}: ${payload.error.message}`
      : `Stripe request failed with status ${response.status}.`;
    throw new Error(sanitizeErrorMessage(message));
  }
  if (!payload || typeof payload !== "object") throw new Error("Stripe response was empty.");
  return payload as T;
};

const readMoneySwitchState = async (adminClient: SupabaseClientLike, key: string) => {
  const { data, error } = await adminClient
    .from("platform_money_kill_switches")
    .select("state")
    .eq("key", key)
    .maybeSingle();
  if (error) throw new Error(`Money switch lookup failed: ${error.message}`);
  return toText((data as { state?: unknown } | null)?.state) || "off";
};

const hasAudienceBlock = async (adminClient: SupabaseClientLike, creatorId: string, fanId: string) => {
  const { data, error } = await adminClient
    .from("channel_audience_blocks")
    .select("channel_user_id")
    .or(`and(channel_user_id.eq.${creatorId},blocked_user_id.eq.${fanId}),and(channel_user_id.eq.${fanId},blocked_user_id.eq.${creatorId})`)
    .limit(1);
  if (error) throw new Error(`Block lookup failed: ${error.message}`);
  return Array.isArray(data) && data.length > 0;
};

const readCreatorDisplayName = async (adminClient: SupabaseClientLike, creatorId: string) => {
  const { data, error } = await adminClient
    .from("user_profiles")
    .select("display_name,username")
    .eq("user_id", creatorId)
    .maybeSingle();
  if (error) throw new Error(`Creator profile lookup failed: ${error.message}`);
  const row = data as { display_name?: unknown; username?: unknown } | null;
  return toText(row?.display_name) || toText(row?.username) || "creator";
};

const recentPendingTipAttempts = async (adminClient: SupabaseClientLike, fanId: string, creatorId: string) => {
  const since = new Date(Date.now() - 15_000).toISOString();
  const { count, error } = await adminClient
    .from("creator_tip_transactions")
    .select("id", { count: "exact", head: true })
    .eq("sender_id", fanId)
    .eq("creator_id", creatorId)
    .in("status", ["pending", "checkout_started"])
    .gte("created_at", since);
  if (error) throw new Error(`Tip rate-limit lookup failed: ${error.message}`);
  return Number(count ?? 0);
};

const readTipSettings = async (adminClient: SupabaseClientLike, creatorId: string) => {
  const { data, error } = await adminClient
    .from("creator_tip_settings")
    .select("creator_id,tips_enabled,status,currency,min_amount_cents,max_amount_cents,provider_charges_enabled,provider_payouts_enabled")
    .eq("creator_id", creatorId)
    .maybeSingle();
  if (error) throw new Error(`Tip settings lookup failed: ${error.message}`);
  return data as TipSettingsRow | null;
};

const payoutAccountReadyForTip = (account: PayoutAccountRow | null) =>
  !!account && account.charges_enabled === true && account.payouts_enabled === true
  && account.onboarding_status === "ready_for_payouts"
  && storedStripeConfiguration(account).configurationStatus === "match";

const syncSettingsFromPayout = async (
  adminClient: SupabaseClientLike,
  creatorId: string,
  settings: TipSettingsRow | null,
  payoutAccount: PayoutAccountRow | null,
) => {
  if (!settings) return null;
  const providerStatus = toText(payoutAccount?.onboarding_status) || "setup_required";
  const chargesEnabled = payoutAccount?.charges_enabled === true;
  const payoutsEnabled = payoutAccount?.payouts_enabled === true;
  const status = settings.tips_enabled === true && payoutAccountReadyForTip(payoutAccount)
    ? "active"
    : settings.tips_enabled === true && providerStatus === "payouts_disabled"
      ? "blocked"
      : settings.tips_enabled === true
        ? "setup_incomplete"
        : "paused";

  const { data, error } = await adminClient
    .from("creator_tip_settings")
    .update({
      provider_account_id: toText(payoutAccount?.provider_account_id) || null,
      provider_charges_enabled: chargesEnabled,
      provider_onboarding_status: providerStatus,
      provider_payouts_enabled: payoutsEnabled,
      status,
      updated_at: new Date().toISOString(),
    })
    .eq("creator_id", creatorId)
    .select("creator_id,tips_enabled,status,currency,min_amount_cents,max_amount_cents,provider_charges_enabled,provider_payouts_enabled")
    .single();
  if (error) throw new Error(`Tip settings provider sync failed: ${error.message}`);
  return data as TipSettingsRow;
};

Deno.serve(async (req): Promise<Response> => {
  if (req.method === "OPTIONS") return optionsResponse();
  if (req.method !== "POST") {
    return jsonResponse(405, { error: "method_not_allowed", message: "Use POST for tip checkout requests." });
  }

  let adminClient: SupabaseClientLike | null = null;
  let currentUser: AuthenticatedUser | null = null;
  let tipId: string | null = null;
  let attemptResponse: Record<string, unknown> | null = null;

  try {
    const { supabaseAnonKey, supabaseUrl } = createAuthClient();
    const authResult = await authenticateRequest(req, supabaseUrl, supabaseAnonKey);
    if ("error" in authResult) return authResult.error;
    currentUser = authResult.user;
    const authorization = toText(req.headers.get("Authorization"));
    const buyerAuthorityClient = createClient(supabaseUrl, supabaseAnonKey, {
      auth: { autoRefreshToken: false, persistSession: false },
      global: { headers: { Authorization: authorization } },
    });

    const adminConfig = createAdminClient();
    if (!adminConfig.configured) {
      return jsonResponse(200, notConfiguredPayload(adminConfig.reason, adminConfig.message, {
        checkoutCreated: false,
        tipCreated: false,
      }));
    }
    adminClient = adminConfig.client;

    const buyerAuthority = await readBuyerSessionAuthority(buyerAuthorityClient, currentUser.id);
    if (!buyerAuthority) {
      return jsonResponse(403, {
        error: "buyer_authority_required",
        checkoutCreated: false,
        liveMoneyAction: false,
        message: "An active unrestricted account session is required before starting a tip.",
      });
    }

    const parsed = await parseJsonPayload<TipCheckoutPayload>(req);
    if ("error" in parsed) {
      return parsed.error ?? jsonResponse(400, {
        error: "invalid_body",
        message: "Request body could not be verified.",
      });
    }

    const creatorId = normalizeUuid(parsed.value.creator_id ?? parsed.value.creatorId);
    const amountCents = toAmountCents(parsed.value.amount_cents ?? parsed.value.amountCents);
    const currency = toText(parsed.value.currency || "usd").toLowerCase();
    const privateNote = sanitizePrivateNote(parsed.value.private_note ?? parsed.value.privateNote);
    const requestId = normalizeUuid(parsed.value.request_id ?? parsed.value.requestId);
    if (!requestId) return jsonResponse(400, { error: "tip_request_id_required", message: "Use a durable tip checkout attempt." });

    if (!creatorId) return jsonResponse(400, { error: "creator_required", message: "Choose a creator to tip." });
    if (creatorId === currentUser.id) return jsonResponse(403, { error: "self_tip_blocked", message: "Creators cannot tip themselves." });
    if (currency !== "usd") return jsonResponse(400, { error: "unsupported_currency", message: "Tips are only available in USD for this test." });
    if (!amountCents || amountCents <= 0) return jsonResponse(400, { error: "invalid_amount", message: "Choose a tip amount." });

    const [tipsSwitch, liveMoneySwitch, providerWebhookSwitch] = await Promise.all([
      readMoneySwitchState(adminClient, "tips_enabled"),
      readMoneySwitchState(adminClient, "live_money_enabled"),
      readMoneySwitchState(adminClient, "provider_webhooks_enabled"),
    ]);

    if (!["on", "sandbox_only"].includes(tipsSwitch)) {
      return jsonResponse(403, { error: "tips_disabled", message: "Tips are unavailable right now." });
    }
    if (!["on", "sandbox_only"].includes(providerWebhookSwitch)) {
      return jsonResponse(403, { error: "webhook_disabled", message: "Payments are unavailable right now." });
    }
    if (liveMoneySwitch === "on") {
      return jsonResponse(403, { error: "live_mode_not_approved", message: "Tips V1 is test mode only until live approval." });
    }

    const stripeSecret = readStripeTestSecret();
    if (!stripeSecret.configured) {
      return jsonResponse(200, notConfiguredPayload(stripeSecret.reason, stripeSecret.message, {
        checkoutCreated: false,
        tipCreated: false,
      }));
    }

    const [initialSettings, payoutAccount, blocked, recentAttempts, creatorDisplayName] = await Promise.all([
      readTipSettings(adminClient, creatorId),
      readCreatorPayoutAccount(adminClient, creatorId, "test") as Promise<PayoutAccountRow | null>,
      hasAudienceBlock(adminClient, creatorId, currentUser.id),
      recentPendingTipAttempts(adminClient, currentUser.id, creatorId),
      readCreatorDisplayName(adminClient, creatorId),
    ]);

    if (blocked) return jsonResponse(403, { error: "audience_blocked", message: "Tips are unavailable for this creator." });
    if (recentAttempts >= 3) return jsonResponse(429, { error: "too_many_tip_attempts", message: "Wait a moment before starting another tip." });
    if (!initialSettings?.tips_enabled) return jsonResponse(403, { error: "tips_not_enabled", message: "This creator has not enabled tips." });

