  const key = readOptionalEnv("STRIPE_CASHOUT_TEST_KEY");
  if (!key || !/^(sk|rk)_test_[A-Za-z0-9]+$/.test(key)) return jsonResponse(503, { error: "sandbox_cashout_not_configured" });
