import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { confirmDistinctLiveConnectSetup, createOrRecoverLiveConnectAccount, selectConnectOnboardingRoute } from "../_shared/stripe-connect-live-onboarding.ts";

import {
  authenticateRequest,
  createAdminClient,
  createAuthClient,
  createStripeConnectAccount,
  hasClientProviderAccountId,
  jsonResponse,
  normalizeStripeAccount,
  notConfiguredPayload,
  optionsResponse,
  parseJsonPayload,
  readCreatorPayoutAccount,
  readStripeTestSecret,
  requestedAccountType,
  requestedCreatorUserId,
  safeAccountStatusPayload,
  safeWriteAuditLog,
  sanitizeErrorMessage,
  safeStripeConfigurationPayload,
  storedStripeConfiguration,
  stripeConfigurationNotice,
  type AuthenticatedUser,
  type StripeConnectAccountPayload,
  type SupabaseClientLike,
  upsertCreatorPayoutAccountFromStripe,
  writeAuditLog,
} from "../_shared/stripe-connect.ts";

const FUNCTION_NAME = "stripe-connect-account";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return optionsResponse();
  if (req.method !== "POST") {
    return jsonResponse(405, { error: "method_not_allowed", message: "Use POST for Stripe Connect account requests." });
  }

  let adminClient: SupabaseClientLike | null = null;
  let currentUser: AuthenticatedUser | null = null;
  let selectedMode: "test" | "live" = "test";

  try {
    const { supabaseAnonKey, supabaseUrl } = createAuthClient();
    const authResult = await authenticateRequest(req, supabaseUrl, supabaseAnonKey);
    if ("error" in authResult) return authResult.error;
    currentUser = authResult.user;

    const parsed = await parseJsonPayload<StripeConnectAccountPayload>(req);
    if ("error" in parsed) return parsed.error;

    if (hasClientProviderAccountId(parsed.value)) {
      return jsonResponse(400, {
        error: "provider_account_id_not_allowed",
        message: "Provider account ids are backend-owned and are not accepted from the client.",
      });
    }

    const requestedCreatorId = requestedCreatorUserId(parsed.value);
    if (requestedCreatorId && requestedCreatorId !== currentUser.id) {
      return jsonResponse(403, {
        error: "creator_mismatch",
        message: "Creator payout setup can only be requested for the current authenticated creator.",
      });
    }

    const accountType = requestedAccountType(parsed.value);
    if (accountType && accountType !== "express") {
      return jsonResponse(400, {
        error: "unsupported_account_type",
        message: "Stripe Connect payout setup requires the server-qualified Express configuration.",
      });
    }

    const adminConfig = createAdminClient();
    if (!adminConfig.configured) {
      return jsonResponse(200, notConfiguredPayload(adminConfig.reason, adminConfig.message, { creatorUserId: currentUser.id }));
    }
    adminClient = adminConfig.client;

    let route = await selectConnectOnboardingRoute(adminClient, currentUser);
    if (route.mode === "test" && route.status && route.status !== "available") return jsonResponse(200, {
      mode: "test", status: route.status, liveMoneyAction: false, accountCreated: false,
      reason: route.reason,
      message: route.reason === "live_setup_required"
        ? "Live payout setup is not configured yet. Your existing payout account and history remain unchanged."
        : "Complete eligible adult creator status and the current payout terms before starting provider setup.",
    });
    if (route.mode === "live" && route.status === "live_setup_confirmation_required" && parsed.value.live_setup_disclosure === "distinct-live-account-v1") {
      route = await confirmDistinctLiveConnectSetup(adminClient, currentUser, parsed.value.live_setup_disclosure);
    }
    if (route.mode === "live") {
      selectedMode = "live";
      if (route.status !== "available") return jsonResponse(200, { ...route, liveMoneyAction: false, accountCreated: false,
        message: route.status === "live_setup_confirmation_required"
          ? "Set up a separate live Stripe payout account? Your test account and test history will stay unchanged. Stripe will ask you to complete its identity, bank and agreement steps. This does not enable payments or payouts."
          : route.status === "account_migration_review_required"
          ? "Your existing payout account needs a reviewed transition. It has not been replaced."
          : "Live onboarding requires eligible creator status, current payout terms and qualified provider setup." });
      const secret = Deno.env.get("STRIPE_CONNECT_LIVE_ONBOARDING_KEY") ?? "";
      if (!/^(sk|rk)_live_[A-Za-z0-9]+$/.test(secret)) return jsonResponse(200, { status: "not_configured", mode: "live", liveMoneyAction: false, accountCreated: false });
      return jsonResponse(200, await createOrRecoverLiveConnectAccount(adminClient, currentUser, secret));
    }

    const existingAccount = await readCreatorPayoutAccount(adminClient, currentUser.id);
    const stripeSecret = readStripeTestSecret();
    if (!stripeSecret.configured) {
      return jsonResponse(
        200,
        notConfiguredPayload(stripeSecret.reason, stripeSecret.message, {
          accountCreated: false,
          accountReused: !!existingAccount?.provider_account_id,
          creatorUserId: currentUser.id,
          providerAccountPresent: !!existingAccount?.provider_account_id,
        }),
      );
    }

    const requestedAuditId = await writeAuditLog(adminClient, {
      action: "stripe_connect_account_create_requested",
      actorEmail: currentUser.email,
      actorUserId: currentUser.id,
      metadata: {
        function_name: FUNCTION_NAME,
        provider_account_present: !!existingAccount?.provider_account_id,
        requested_account_type: accountType ?? "express",
      },
      targetId: existingAccount?.id ?? null,
      targetType: "creator_payout_account",
      targetUserId: currentUser.id,
    });

    if (existingAccount?.provider_account_id) {
      const configuration = storedStripeConfiguration(existingAccount);
      return jsonResponse(200, {
        status: configuration.configurationStatus === "match" ? "account_reused" : "configuration_review_required",
        provider: "stripe",
        providerKey: "stripe_connect",
        mode: "test",
        liveMoneyAction: false,
        creatorUserId: currentUser.id,
        providerAccountPresent: true,
        providerCall: false,
        providerWrite: false,
        accountCreated: false,
        configuration: safeStripeConfigurationPayload(configuration),
        audit: {
          requested: true,
          requestedAuditLogId: requestedAuditId,
        },
        message: configuration.configurationStatus === "match"
          ? "Existing Stripe Connect test-mode payout account reference was reused. No new provider account was created."
          : stripeConfigurationNotice(configuration.configurationStatus),
      });
    }

    const dispatchRoute = await selectConnectOnboardingRoute(adminClient, currentUser);
    if (dispatchRoute.mode !== "test" || (dispatchRoute.status && dispatchRoute.status !== "available")) {
      return jsonResponse(200, { status: "onboarding_authority_changed", mode: "test", liveMoneyAction: false, accountCreated: false });
    }
    const stripeAccount = await createStripeConnectAccount(stripeSecret.secret, currentUser);
    const normalizedAccount = normalizeStripeAccount(stripeAccount);
    const accountRow = await upsertCreatorPayoutAccountFromStripe(
      adminClient,
      currentUser.id,
      normalizedAccount,
      existingAccount,
      requestedAuditId,
      FUNCTION_NAME,
    );

    const createdAuditId = await writeAuditLog(adminClient, {
      action: "stripe_connect_account_created",
      actorEmail: currentUser.email,
      actorUserId: currentUser.id,
      afterState: safeAccountStatusPayload(normalizedAccount),
      metadata: {
        function_name: FUNCTION_NAME,
        provider_account_id: normalizedAccount.id,
      },
      targetId: accountRow.id,
      targetType: "creator_payout_account",
      targetUserId: currentUser.id,
    });

    await upsertCreatorPayoutAccountFromStripe(
      adminClient,
      currentUser.id,
      normalizedAccount,
      accountRow,
      createdAuditId,
      FUNCTION_NAME,
    );

    return jsonResponse(200, {
      status: normalizedAccount.configurationStatus === "match" ? "configured" : "configuration_review_required",
      provider: "stripe",
      providerKey: "stripe_connect",
      mode: "test",
      liveMoneyAction: false,
      creatorUserId: currentUser.id,
      providerAccountPresent: true,
      providerCall: true,
      providerWrite: true,
      accountCreated: true,
      payoutCreated: false,
      transferCreated: false,
      checkoutCreated: false,
      account: safeAccountStatusPayload(normalizedAccount),
      audit: {
        created: true,
        createdAuditLogId: createdAuditId,
        requested: true,
        requestedAuditLogId: requestedAuditId,
      },
      message: normalizedAccount.configurationStatus === "match"
        ? "Stripe Connect test-mode account was created. Payout execution remains inactive."
        : stripeConfigurationNotice(normalizedAccount.configurationStatus),
    });
  } catch (error) {
    await safeWriteAuditLog(adminClient, {
      action: "stripe_connect_error",
      actorEmail: currentUser?.email ?? null,
      actorUserId: currentUser?.id ?? null,
      metadata: {
        error: sanitizeErrorMessage(error),
        function_name: FUNCTION_NAME,
      },
      severity: "warning",
      targetType: "creator_payout_account",
      targetUserId: currentUser?.id ?? null,
    });

    return jsonResponse(500, {
      error: "stripe_connect_account_failed",
      liveMoneyAction: false,
      message: sanitizeErrorMessage(error),
      provider: "stripe",
      providerKey: "stripe_connect",
      mode: selectedMode,
    });
  }
});

